from collections import Counter, defaultdict
from typing import Any

from sympy import Rational
from pymatgen.core import Structure
from pymatgen.symmetry.analyzer import SpacegroupAnalyzer


def _rational_str(value: float, max_denominator: int = 12) -> str:
    """Convert a fractional coordinate to a simple rational string."""
    rat = Rational(str(float(value))).limit_denominator(max_denominator)
    return str(rat)


def analyze_wyckoff_position_multiplicities_and_coordinates(
    filepath: str,
) -> dict[str, dict] | dict[str, Any]:
    """Analyze Wyckoff multiplicities and representative coordinates from a CIF.

    Parameters
    ----------
    filepath
        Path to the CIF file.

    Returns
    -------
    dict
        {
            "wyckoff_multiplicity_dict": {letter: multiplicity, ...},
            "wyckoff_coordinates_dict": {letter: [x, y, z], ...}
        }
    """
    try:
        structure = Structure.from_file(filepath)
        sga = SpacegroupAnalyzer(structure)
        dataset = sga.get_symmetry_dataset()
        if dataset is None or not hasattr(dataset, "wyckoffs"):
            return {"wyckoff_multiplicity_dict": {}, "wyckoff_coordinates_dict": {}}

        wyckoff_letters = list(dataset.wyckoffs)
        multiplicity_dict = dict(sorted(Counter(wyckoff_letters).items()))

        representative_sites = defaultdict(list)
        for idx, letter in enumerate(wyckoff_letters):
            representative_sites[letter].append(structure[idx])

        coordinates_dict: dict[str, list[str]] = {}
        for letter in sorted(representative_sites):
            coords = representative_sites[letter][0].frac_coords
            coordinates_dict[letter] = [_rational_str(c, max_denominator=12) for c in coords]

        return {
            "wyckoff_multiplicity_dict": multiplicity_dict,
            "wyckoff_coordinates_dict": coordinates_dict,
        }
    except Exception as exc:
        return {"error": str(exc)}


if __name__ == "__main__":
    import json
    import sys

    if len(sys.argv) != 2:
        print("Usage: python solution.py <cif-file>")
        raise SystemExit(1)

    print(json.dumps(analyze_wyckoff_position_multiplicities_and_coordinates(sys.argv[1]), indent=2))
